+ * Factory that creates {@link KmpSearchProcessor}.
+ * Use static {@link SearchProcessorFactory#newKmpSearchProcessorFactory}
+ * to create an instance of this factory.
+ * @see SearchProcessorFactory
+ */
+public class KmpSearchProcessorFactory extends SearchProcessorFactory {
+
+    private final int[] next;
+    private final byte[] needle;
+
+    KmpSearchProcessorFactory(byte[] needle) {
+        this.needle = needle;
+        this.next = new int[needle.length + 1];
+
+        int j = 0;
+        for (int i = 1; i < needle.length; i++) {
+            while (j > 0 && needle[j] != needle[i]) {
+                j = next[j];
+            }
+            if (needle[j] == needle[i]) {
+                j++;
+            }
+            next[i + 1] = j;
+        }
+    }
+
+    /**
+     * Returns a new {@link KmpSearchProcessor}.
+     */
+    @Override
+    public KmpSearchProcessor newSearchProcessor() {
+        return new KmpSearchProcessor(needle, next);
+    }
+
+};

