+        assertEquals(-1, haystack.forEachByte(6, length - 6, processor));
+
+        haystack.release();
+    }
+
+    private SearchProcessorFactory factory(String needle) {
+        return algorithm.newFactory(needle.getBytes(CharsetUtil.UTF_8));
+    }
